  "fund.withSplitExpensesFund": "Із «Ділити витрати» фонд підраховує, хто кому скільки винен – наприклад, для спільних квартир, відпусток або пари. Списки покупок можна прив’язати до фонду в розділі Списки → Редагувати список. «Сім’я (усі)» автоматично належить усім і містить договори без власного фонду.",
