  "loc.enterInternetConnectionsAddress": "Вкажи адресу свого інтернет-підключення як сервер (напр. адресу MyFRITZ!) – зазвичай SMS-командою згідно з посібником трекера.",
  "loc.enterShopAddressesUnder": "Адреси магазинів ти вказуєш у розділі Списки → Редагувати список покупок – якщо магазин існує в кількох місцях, то й кілька філій. Якщо хтось там певний час перебуває, запланований похід за покупками позначається виконаним.",
