  "loc.familyGetsMessageSees": "Сім’я отримає повідомлення й бачитиме твоє місцезнаходження наживо, доки ти не дістанешся додому. Вирушати?",
  "loc.familyGetsMessageSees#wg": "Квартира отримає повідомлення й бачитиме твоє місцезнаходження наживо, доки ти не дістанешся додому. Вирушати?",
