  "loc.fromPinn": "з pinn.",
  "loc.fromTraccar": "із «Traccar Client»",
  "loc.gettingLocation": "Визначення місцезнаходження …",
  "loc.gpsTracker": "🛰️ GPS-трекер",
  "loc.guide1": "Встанови застосунок <b>«Traccar Client»</b> (App Store або Google Play, безкоштовно).",
  "loc.guide2": "У застосунку в полі <b>Device ID</b> (ідентифікатор пристрою) вкажи:",
  "loc.guide3": "У полі <b>Server URL</b> вкажи:",
  "loc.guide4": "Точність <b>Medium</b>, відстань <b>50 м</b>. Тоді застосунок надсилає дані лише під час руху – нічого, поки ти стоїш. Якщо є більше полів (інтервал, heartbeat), вимкни heartbeat або постав 0.",
  "loc.guide5": "Дозволь доступ до місцезнаходження: <b>Завжди</b> і <b>Точне місцезнаходження</b> – увімкнено.",
  "loc.guide6": "Увімкни перемикач <b>Service / Tracking</b> і <b>завжди залишай його ввімкненим</b> – готово. Відтепер усім керуєш у pinn.: «Надсилати постійно» увімк. або вимк., «Надіслати один раз» і SOS. Поки «Надсилати постійно» вимкнено, ніхто не бачить твоє місцезнаходження, а pinn. не записує маршрут.",
  "loc.guideIntro": "Без іншого застосунку «📍 Поділитися місцезнаходженням» працює безпосередньо в pinn. – але лише поки pinn. відкритий. Щоб місцезнаходження надходило й тоді, коли pinn. закритий, а екран заблокований, безкоштовний застосунок «Traccar Client» надсилає його прямо в pinn. (сервер Traccar не потрібен). Однаково для iPhone і Android.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Цей порт потрібно перенаправити на NAS у FRITZ!Box, бо трекер підключається з мобільної мережі.",
  "loc.haveGoodTripFamily": "Гарної дороги! Сім’ю повідомлено.",
  "loc.haveGoodTripFamily#wg": "Гарної дороги! Квартиру повідомлено.",
