  "loc.ifSomeoneArrivesLeaves": "Коли хтось прибуває в місце або залишає його, надходить push-сповіщення. «Дім» також завершує «Я в дорозі додому».",
  "loc.ifTrackerHasSos": "Якщо в трекера є кнопка SOS, pinn. сповіщає всю сім’ю через push (протягом хвилини), щойно Traccar виявляє сигнал тривоги трекера.",
