  "loc.serverData": "Дані сервера",
  "loc.serverDoesntHaveFunction": "Сервер ще не має цієї функції – встанови pinn-ortung.js і ortung.pb.js та перезапусти PocketBase.",
  "loc.setSendIntervalE": "Встанови інтервал надсилання, напр. 60 секунд.",
  "loc.setUpLocation": "Налаштувати місцезнаходження",
  "loc.setup": "Налаштування · {famDeviceName}",
  "loc.setupIntro": "Телефонам більше нічого не потрібно: кожен може ділитися безпосередньо в pinn. у розділі «Моє місцезнаходження». У фоні (коли pinn. закритий) телефон надсилає дані через безкоштовний застосунок «Traccar Client» (iPhone і Android) – прямо в pinn., сервер Traccar не потрібен. Лише GPS-трекерам із SIM-карткою (напр. на нашийнику) потрібен контейнер «traccar». Місцезнаходження залишаються на твоєму NAS.",
  "loc.setupTrackersUnder": "GPS-трекери та фоновий застосунок ти налаштовуєш через {btn}.",
  "loc.shareAlreadyEnded": "Твоє передавання вже завершилося.",
  "loc.shareIntro": "Сім’я бачить тебе наживо на карті. Дані надсилаються лише під час руху – нічого, поки ти стоїш. Коли pinn. закритий, надсилає застосунок «Traccar Client», який ти налаштував(-ла) один раз.",
  "loc.shareIntro#wg": "Квартира бачить тебе наживо на карті. Дані надсилаються лише під час руху – нічого, поки ти стоїш. Коли pinn. закритий, надсилає застосунок «Traccar Client», який ти налаштував(-ла) один раз.",
  "loc.sharedUntil": "передається {until}",
