  "loc.shops": "🛒 Магазини",
  "loc.showsWhatTraccarClient": "Показує, що «Traccar Client» надсилає в pinn. Після натискання SOS тут має з’явитися «🆘 виявлено».",
  "loc.simContainer": "SIM-картка · контейнер «traccar»",
  "loc.sosAlwaysPush": "У разі надзвичайної ситуації (SOS) сім’я завжди отримує push-повідомлення.",
  "loc.sosAlwaysPush#wg": "У разі надзвичайної ситуації (SOS) квартира завжди отримує push-повідомлення.",
  "loc.sosDetected": "🆘 виявлено",
