  "loc.sosTestSent": "Тест SOS надіслано",
  "loc.startSending": "Почати надсилання",
  "loc.streetTown": "Вулиця, місто",
  "loc.testSameProcessReal": "Тест: той самий процес, що й справжній заклик про допомогу (push, спливне вікно, карта, адреса) – але лише тобі, сім’я нічого не помічає.",
  "loc.testSameProcessReal#wg": "Тест: той самий процес, що й справжній заклик про допомогу (push, спливне вікно, карта, адреса) – але лише тобі, квартира нічого не помічає.",
  "loc.tipSetAddressUnder": "Підказка: вкажи свою адресу в розділі Налаштування → Дім – тоді місце «Дім» з’явиться автоматично, з push під час прибуття й відходу.",
  "loc.traccarClientChooseSend": "У «Traccar Client» обери «Send SOS» (залежно від версії – в застосунку або довгим натисканням на значок застосунку). pinn. негайно сповіщає всіх членів сім’ї через push – з місцезнаходженням, адресою, часом і кнопками для дзвінка та екстреного виклику {regionNotrufText}. Підказка: вкажи власний номер мобільного в екстреній картці.",
  "loc.traccarClientChooseSend#wg": "У «Traccar Client» обери «Send SOS» (залежно від версії – в застосунку або довгим натисканням на значок застосунку). pinn. негайно сповіщає всіх співмешканців через push – з місцезнаходженням, адресою, часом і кнопками для дзвінка та екстреного виклику {regionNotrufText}. Підказка: вкажи власний номер мобільного в екстреній картці.",
  "loc.traccarSetUpShownWhen": "«Traccar Client» налаштовано – тебе буде видно лише після того, як ти почнеш надсилати постійно.",
