  "settings.outlook.intro#wg": "Щонеділі з 18:00 надходить тижневий огляд із усім важливим для квартири на наступний тиждень, а в останній день місяця з 18:00 – прогноз фінансів на наступний місяць. Обидва з’являються один раз як повідомлення вгорі та як push-сповіщення – ти можеш будь-коли відкрити їх тут знову.",
