  "smart.autoInfo": "Команда на iPhone або iPad удома в певний час запитує в pinn., що має запуститися зараз, і запускає це. Вона також надолужує дії «Під час позначки виконаним», якщо завдання позначили на пристрої без команд (напр. Android). Посилання містить секретний ключ і показує лише цей список. Діє лише для пристроїв через Команди Apple.",
