  "smart.haIntro": "Сервер pinn. керує Home Assistant безпосередньо – кнопки працюють на кожному пристрої (зокрема Android), автоматизація й «Під час позначки виконаним» працюють без команд. Із сутністю стану pinn. чекає, доки, наприклад, робот-пилосос справді завершить роботу.",
