  "voice.widgetIntro": "Показує події, завдання та список покупок на головному екрані й на годиннику – лише перегляд. Використовується те саме секретне посилання, що й вище.",
  "voice.widgetIos1": "Встановіть безкоштовний застосунок <b>Scriptable</b> з App Store, відкрийте його й торкніться <b>+</b> угорі праворуч.",
  "voice.widgetIos2": "Торкніться тут у pinn. «Скопіювати скрипт віджета», вставте текст у Scriptable і назвіть скрипт <b>pinn</b>.",
  "voice.widgetIos3": "Утримуйте головний екран → <b>+</b> → <b>Scriptable</b> → оберіть розмір → торкніться віджета → у полі «Script» оберіть <b>pinn</b>. iOS оновлює його приблизно кожні 15 хвилин.",
  "voice.widgetIosTitle": "Віджет для iPhone через Scriptable",
