  "voice.widgetNote": "Як і з Siri, iPhone має мати доступ до pinn. (домашній Wi-Fi або VPN). Посилання працює як пароль – не передавайте його.",
  "voice.widgetPick": "Що показувати у віджеті? Позначте й скопіюйте скрипт – окремий скрипт для кожного віджета.",
  "voice.widgetQuickCopy": "🔗 Скопіювати скрипт швидкого доступу",
  "voice.widgetQuickHint": "Швидкий доступ: віджет із трьома кнопками – списки, фінанси (зі знаком валюти вашого регіону) та завдання. Дотик відкриває цю сторінку pinn. у Safari, а не в установленому застосунку, тож увійдіть там один раз.",
  "voice.widgetScriptCopied": "Скрипт скопійовано.",
  "voice.widgetTasks": "Завдання (без домашніх)",
  "voice.widgetTick": "У середньому й великому віджеті торкніться завдання, щоб відзначити його – у pinn. воно теж буде відзначене. iOS ненадовго відкриває Scriptable.",
  "voice.widgetTitle": "📲 Віджети та ⌚ Apple Watch",
  "voice.widgetViews": "Інший вигляд: у посиланні замініть <code>ansicht=heute</code> на <code>morgen</code>, <code>einkauf</code> або <code>alles</code>.",
  "voice.widgetWatch1": "У застосунку <b>«Команди»</b> на iPhone створіть нову команду й додайте дію <b>«Отримати вміст URL»</b>.",
